import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class EducationalRound86E {

    private static final long MOD = 998244353L;
    private static final int MAX = (int)4e5 + 10;
    private static long[] factorial;
    private static long[] inverseFactorial;

    private static void precompute() {
        factorial = new long[MAX];
        inverseFactorial = new long[MAX];
        factorial[0] = factorial[1] = inverseFactorial[0] = inverseFactorial[1] = 1L;
        for (int i = 2; i < MAX; i++) {
            factorial[i] = (factorial[i - 1] * (long)i) % MOD;
            inverseFactorial[i] = (inverseFactorial[i - 1] * modularInverse(i, MOD)) % MOD;
        }
    }

    private static long nCr(int n, int r) {
        long result = factorial[n] * inverseFactorial[r] % MOD;
        result = result * inverseFactorial[n - r] % MOD;
        return result;
    }

    private static long fastPow(long base, long exp) {
        if (exp == 0) return 1L;
        long half = fastPow(base, exp / 2);
        half = half * half % MOD;
        if ((exp & 1) == 1) {
            half = half * base % MOD;
        }
        return half;
    }

    private static void solve() {
        precompute();
        int n = reader.nextInt();
        long k = reader.nextLong();
        if (k == 0) {
            writer.println(factorial[n]);
            return;
        }
        if (n <= k) {
            writer.println(0);
            return;
        }
        long comb = nCr(n, (int)k);
        int cols = n - (int)k;
        long sum = 0L;
        for (int i = 0; i <= cols; i++) {
            long term = nCr(cols, i);
            term = term * fastPow(cols - i, n) % MOD;
            if ((i & 1) == 1) {
                sum -= term;
                if (sum < 0) sum += MOD;
            } else {
                sum += term;
                if (sum >= MOD) sum -= MOD;
            }
        }
        writer.println((2L * ((comb * sum) % MOD)) % MOD);
    }

    public static void main(String[] args) {
        writer = new PrintWriter(new BufferedOutputStream(System.out));
        reader = new FastReader();
        solve();
        writer.close();
    }

    private static class Triplet {
        long gcd;
        long x;
        long y;

        Triplet(long gcd, long x, long y) {
            this.gcd = gcd;
            this.x = x;
            this.y = y;
        }
    }

    private static Triplet extendedEuclidean(long a, long b) {
        if (a == 0) {
            return new Triplet(b, 0, 1);
        }
        Triplet temp = extendedEuclidean(b % a, a);
        long x = temp.y - (b / a) * temp.x;
        long y = temp.x;
        return new Triplet(temp.gcd, x, y);
    }

    private static long modularInverse(long a, long m) {
        Triplet result = extendedEuclidean(a, m);
        if (result.gcd != 1) {
            return -1;
        } else {
            return (result.x % m + m) % m;
        }
    }

    private static FastReader reader;
    private static PrintWriter writer;

    private static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (Exception e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}
